# ---------------------------------------------------------
# Request Timing Profiles (nmap -T0..-T5 style pacing) & Throttled Request Helper
# ---------------------------------------------------------
# (delay_low, delay_high) seconds of randomized jitter before each request,
# plus a max worker count for ThreadPoolExecutor stages. Slower profiles
# exist so a scan doesn't get silently rate-limited/blocked mid-run — a
# blocked response can otherwise misread as "no WAF / no protection".
TIMING_PROFILES = {
    "🐢 Paranoid (T0)":   ((8.0, 15.0), 2),
    "🐌 Sneaky (T1)":     ((3.0, 6.0), 3),
    "🚶 Polite (T2)":     ((1.0, 2.5), 5),
    "⚖️ Normal (T3)":     ((0.3, 0.8), 10),
    "🏃 Aggressive (T4)": ((0.0, 0.2), 15),
    "⚡ Insane (T5)":     ((0.0, 0.0), 25),
}

def throttled_request(method, url, delay_range=(0.0, 0.0), max_retries=3, **kwargs):
    """
    Wraps requests.get/requests.post with:
      1. Randomized jitter delay before firing (based on the selected timing profile)
      2. Automatic exponential backoff + retry on 429 (Too Many Requests) / 403 (Forbidden)

    This is the nmap -T0..-T5 equivalent for HTTP-based recon: it keeps the scanner
    from tripping rate limiters mid-scan, which otherwise shows up as a false
    "target looks unprotected" reading once real responses start getting swapped
    for block-pages or empty 403s.
    """
    low, high = delay_range
    if high > 0:
        time.sleep(random.uniform(low, high))
    resp = None
    for attempt in range(max_retries):
        try:
            resp = method(url, **kwargs)
        except Exception:
            raise
        if resp.status_code in (429, 403) and attempt < max_retries - 1:
            time.sleep((2 ** attempt) + random.uniform(0, 1))
            continue
        return resp
    return resp

# --- Speed helpers -----------------------------------------------------------
# Cap DNS waits so one dead resolver / missing record can't stall a module for 5s+.
try:
    dns.resolver.get_default_resolver().timeout = 2.0
    dns.resolver.get_default_resolver().lifetime = 4.0
except Exception:
    pass

def _pmap(fn, items, workers=8):
    """Order-preserving parallel map (threads). Used for I/O-bound lookups."""
    items = list(items)
    if not items:
        return []
    with ThreadPoolExecutor(max_workers=max(1, min(workers, len(items)))) as ex:
        return list(ex.map(fn, items))

def _inner_workers(delay_range, n, cap=6):
    """Probes that hit the TARGET stay sequential on stealth profiles (T0-T2, delay >= 1s)
    so the timing profile still means what it says; faster profiles probe in parallel."""
    return 1 if delay_range[1] >= 1.0 else max(1, min(n, cap))

