def highlight_risk_and_status(val):
    val_str = str(val).upper()
    if val_str in ["CRITICAL", "VULNERABLE", "ACTION REQUIRED"]:
        return 'background-color: rgba(239, 68, 68, 0.2); color: #f87171; font-weight: 600; border-radius: 6px;'
    elif val_str in ["HIGH"]:
        return 'background-color: rgba(249, 115, 22, 0.2); color: #fb923c; font-weight: 600; border-radius: 6px;'
    elif val_str in ["MEDIUM", "WARNING", "OPTIMIZATION NEEDED"]:
        return 'background-color: rgba(234, 179, 8, 0.2); color: #facc15; font-weight: 600; border-radius: 6px;'
    elif val_str in ["LOW"]:
        return 'background-color: rgba(56, 189, 248, 0.2); color: #38bdf8; border-radius: 6px;'
    elif val_str in ["SAFE", "PASS", "CLEAN"]:
        return 'background-color: rgba(34, 197, 94, 0.2); color: #4ade80; font-weight: 600; border-radius: 6px;'
    return ''

def format_url(url):
    url = url.strip()
    if not url.startswith("http://") and not url.startswith("https://"):
        url = "http://" + url
    return url

def detect_waf_and_tech(response):
    headers = {k.lower(): str(v).lower() for k, v in response.headers.items()}
    cookies = {k.lower(): str(v).lower() for k, v in response.cookies.items()}
    server = headers.get("server", "")
    body = response.text.lower()

    wafs = []

    if "cloudflare" in server or "cf-ray" in headers or "__cfduid" in cookies or "cf-cache-status" in headers:
        wafs.append("Cloudflare WAF")
    if "aws" in server or "awselb" in server or "x-amz-cf-id" in headers or "aws-waf-token" in cookies:
        wafs.append("AWS WAF / CloudFront")
    if "akamai" in server or "akamaighost" in server or "x-akamai-transformed" in headers:
        wafs.append("Akamai WAF")
    if "incapsula" in server or "visid_incap" in cookies or "incap_ses" in cookies:
        wafs.append("Imperva Incapsula WAF")
    if "sucuri" in server or "x-sucuri-id" in headers or "x-sucuri-cache" in headers:
        wafs.append("Sucuri WebSite Firewall")
    if "big-ip" in server or "bigipserver" in cookies or "x-cnection" in headers:
        wafs.append("F5 BIG-IP ASM")
    if "mod_security" in server or "modsecurity" in server or "cyberoam" in body:
        wafs.append("ModSecurity OWASP WAF")
    if "barracuda" in server or "barra_counter_session" in cookies:
        wafs.append("Barracuda Web Application Firewall")
    if "fortigate" in server or "fortiweb" in server or "fgtoken" in cookies:
        wafs.append("Fortinet FortiWeb WAF")
    if "ns_af" in cookies or "citrix_ns_id" in cookies or "pw_ns_id" in cookies:
        wafs.append("Citrix NetScaler AppFirewall")
    if "rbzid" in cookies or "x-reblaze-protection" in headers:
        wafs.append("Reblaze WAF")
    if "hascn" in headers or "palo alto" in server:
        wafs.append("Palo Alto Networks WAF")

    # techs: human-readable labels for display. tech_keywords: clean product
    # names for feeding to the NVD keywordSearch API. These used to be the
    # same string, parsed apart later — but decorative words we add for
    # readability ("CMS", "Framework", "Frontend") and the "Powered-By: "
    # prefix aren't real product names, so NVD had nothing to match against
    # and the CVE tab always came back empty. Keeping a separate clean list
    # fixes that without touching what's shown in the Technology Stack line.
    techs = []
    tech_keywords = []
    if "x-powered-by" in headers:
        powered_by_value = headers['x-powered-by'].strip()
        techs.append(f"Powered-By: {powered_by_value}")
        if powered_by_value:
            tech_keywords.append(powered_by_value)
    if "wp-content" in body:
        techs.append("WordPress CMS")
        tech_keywords.append("WordPress")
    if "laravel" in body:
        techs.append("Laravel Framework")
        tech_keywords.append("Laravel")
    if "react" in body or "_react" in body:
        techs.append("React.js Frontend")
        tech_keywords.append("React")
    if "next.js" in headers or "__next" in body:
        techs.append("Next.js")
        tech_keywords.append("Next.js")

    waf_str = ", ".join(set(wafs)) if wafs else "No WAF Detected (Generic Stack)"
    tech_str = ", ".join(techs) if techs else "Generic Web Stack"
    return waf_str, tech_str, tech_keywords

def perform_recon(host, url):
    recon_data = {}
    try: recon_data["ip"] = socket.gethostbyname(host)
    except: recon_data["ip"] = "Resolution Failed"

    def _dns(rtype):
        try: return rtype, [str(r.to_text()) for r in dns.resolver.resolve(host, rtype)]
        except Exception: return rtype, []
    recon_data["dns"] = dict(_pmap(_dns, ['A', 'AAAA', 'MX', 'NS', 'TXT'], 5))

    base = url.rstrip('/')
    def _exists(path):
        try: return requests.get(f"{base}{path}", timeout=3).status_code == 200
        except Exception: return False

    try:
        r = requests.get(url, timeout=5, allow_redirects=True, headers={"User-Agent": f"ARGUS/{ARGUS_VERSION}"})
        recon_data["redirect_chain"] = [resp.url for resp in r.history] + [r.url]
        recon_data["robots_txt"], recon_data["sitemap_xml"] = _pmap(_exists, ["/robots.txt", "/sitemap.xml"], 2)
    except:
        recon_data["redirect_chain"] = [url]
        recon_data["robots_txt"] = False
        recon_data["sitemap_xml"] = False

    return recon_data

DKIM_COMMON_SELECTORS = ["default", "google", "selector1", "selector2", "k1", "s1", "mail", "dkim", "smtp"]

def check_email_security(domain):
    """Checks SPF, DMARC, and (best-effort) DKIM records for a domain via DNS TXT lookups.
    DKIM has no fixed record location — it lives under a per-provider 'selector', so this
    only probes a handful of common selector names rather than guaranteeing full coverage."""
    results = []

    # --- SPF ---
    spf_record = ""
    try:
        for r in dns.resolver.resolve(domain, 'TXT'):
            txt = r.to_text().strip('"')
            if txt.lower().startswith("v=spf1"):
                spf_record = txt
                break
    except Exception:
        pass
    results.append({
        "Check": "SPF Record",
        "Status": "PASS" if spf_record else "VULNERABLE",
        "Details": spf_record if spf_record else "No SPF record found — anyone can spoof emails claiming to be from this domain."
    })

    # --- DMARC ---
    dmarc_record = ""
    dmarc_policy = "none"
    try:
        for r in dns.resolver.resolve(f"_dmarc.{domain}", 'TXT'):
            txt = r.to_text().strip('"')
            if txt.lower().startswith("v=dmarc1"):
                dmarc_record = txt
                m = re.search(r'p=(\w+)', txt, re.IGNORECASE)
                if m: dmarc_policy = m.group(1).lower()
                break
    except Exception:
        pass
    if dmarc_record and dmarc_policy in ("quarantine", "reject"):
        dmarc_status = "PASS"
    elif dmarc_record:
        dmarc_status = "Optimization Needed"
    else:
        dmarc_status = "VULNERABLE"
    results.append({
        "Check": "DMARC Record",
        "Status": dmarc_status,
        "Details": dmarc_record if dmarc_record else "No DMARC record found — spoofed mail that fails SPF/DKIM won't be quarantined or rejected."
    })

    # --- DKIM (best-effort against common selectors) ---
    def _dkim(selector):
        try:
            dns.resolver.resolve(f"{selector}._domainkey.{domain}", 'TXT')
            return selector
        except Exception:
            return None
    found_selectors = [x for x in _pmap(_dkim, DKIM_COMMON_SELECTORS, 9) if x]
    results.append({
        "Check": "DKIM Record",
        "Status": "PASS" if found_selectors else "Optimization Needed",
        "Details": f"Found under selector(s): {', '.join(found_selectors)}" if found_selectors
                   else "No DKIM record found under common selectors — a custom selector may still be in use and simply wasn't checked."
    })

    return results

JS_LIB_PATTERNS = [
    (r'jquery[./\-@]+(\d+\.\d+\.\d+)', 'jQuery'),
    (r'bootstrap[./\-@]+(\d+\.\d+\.\d+)', 'Bootstrap'),
    (r'angular(?:js)?[./\-@]+(\d+\.\d+\.\d+)', 'AngularJS'),
    (r'react(?:-dom)?[./\-@]+(\d+\.\d+\.\d+)', 'React'),
    (r'vue(?:\.js)?[./\-@]+(\d+\.\d+\.\d+)', 'Vue.js'),
    (r'lodash[./\-@]+(\d+\.\d+\.\d+)', 'Lodash'),
    (r'moment[./\-@]+(\d+\.\d+\.\d+)', 'Moment.js'),
    (r'handlebars[./\-@]+(\d+\.\d+\.\d+)', 'Handlebars'),
    # Added: newer/still-actively-used libraries that weren't tracked at all
    # before. AngularJS and Moment.js are both legacy/EOL now, but these are
    # what's actually showing up on sites scanned in 2026.
    (r'alpinejs?[./\-@]+(\d+\.\d+\.\d+)', 'Alpine.js'),
    (r'htmx(?:\.org)?[./\-@]+(\d+\.\d+\.\d+)', 'htmx'),
    (r'axios[./\-@]+(\d+\.\d+\.\d+)', 'Axios'),
    (r'chart(?:\.js)?[./\-@]+(\d+\.\d+\.\d+)', 'Chart.js'),
    (r'd3(?:\.js)?[./\-@]+(\d+\.\d+\.\d+)', 'D3.js'),
    (r'three(?:\.js)?[./\-@]+(\d+\.\d+\.\d+)', 'Three.js'),
    (r'swiper[./\-@]+(\d+\.\d+\.\d+)', 'Swiper'),
    (r'gsap[./\-@]+(\d+\.\d+\.\d+)', 'GSAP'),
]

# Fallback: just the bare library name, for cases with no version string at
# all in the markup (e.g. a minified bundle loaded as "jquery.min.js" or a
# name baked into a bundler-hashed filename). We still want to surface
# "this library is present" even when we can't determine its version.
JS_LIB_NAME_ONLY = [
    (r'jquery', 'jQuery'),
    (r'bootstrap', 'Bootstrap'),
    (r'angular(?:js)?', 'AngularJS'),
    (r'react(?:-dom)?', 'React'),
    (r'vue(?:\.js)?', 'Vue.js'),
    (r'lodash', 'Lodash'),
    (r'moment', 'Moment.js'),
    (r'handlebars', 'Handlebars'),
    (r'alpinejs?', 'Alpine.js'),
    (r'htmx', 'htmx'),
    (r'axios', 'Axios'),
    (r'chart(?:\.js)?', 'Chart.js'),
    (r'd3(?:\.js)?', 'D3.js'),
    (r'three(?:\.js)?', 'Three.js'),
    (r'swiper', 'Swiper'),
    (r'gsap', 'GSAP'),
]

# npm package name for each detected library, used to query OSV.dev live
# (see lookup_osv_vuln below). This is the map that keeps the scanner from
# going stale — OSV.dev's database itself gets new CVEs added continuously,
# so as long as this name mapping is right, newly-disclosed vulnerabilities
# show up automatically with zero code changes.
JS_LIB_NPM_NAME = {
    "jQuery": "jquery", "Bootstrap": "bootstrap", "AngularJS": "angular",
    "React": "react", "Vue.js": "vue", "Lodash": "lodash",
    "Moment.js": "moment", "Handlebars": "handlebars",
    "Alpine.js": "alpinejs", "htmx": "htmx.org", "Axios": "axios",
    "Chart.js": "chart.js", "D3.js": "d3", "Three.js": "three",
    "Swiper": "swiper", "GSAP": "gsap",
}

def lookup_osv_vuln(lib_name, version):
    """
    Live-queries OSV.dev (the OpenSSF/Google-run open vulnerability database,
    aggregating GitHub Advisories, npm audit data, etc.) for a specific
    package@version. No API key needed, no rate limit as of writing.

    This is deliberately the PRIMARY source of truth for JS library vulns —
    not the hardcoded KNOWN_JS_VULNS table below. A hardcoded CVE list is a
    snapshot frozen at whatever date someone last edited the code; a live
    query against a maintained database means new CVEs disclosed after this
    code was written are picked up automatically, with no code changes.
    KNOWN_JS_VULNS is kept only as an offline fallback for when OSV.dev is
    unreachable (network restrictions, timeout, etc).
    """
    npm_name = JS_LIB_NPM_NAME.get(lib_name)
    if not npm_name:
        return None
    try:
        resp = requests.post(
            "https://api.osv.dev/v1/query",
            json={"package": {"name": npm_name, "ecosystem": "npm"}, "version": version},
            timeout=5
        )
        if resp.status_code != 200:
            return None
        vulns = resp.json().get("vulns", [])
        descs = []
        for v in vulns[:5]:  # cap per-library so one library can't dominate the report
            vid = v.get("id", "UNKNOWN-ID")
            summary = v.get("summary") or (v.get("details", "")[:150] if v.get("details") else "No summary available.")
            descs.append(f"{vid} — {summary}")
        return descs  # empty list means "checked, none found"; None means "couldn't check"
    except Exception:
        return None

# Small, hand-curated set of well-known CVEs for old front-end library versions.
# OFFLINE FALLBACK ONLY — lookup_osv_vuln() above is tried first and is what
# actually keeps this scanner current year over year. This table exists
# purely so the JS-library check still returns *something* when OSV.dev
# can't be reached, and is intentionally not treated as the main source.

KNOWN_JS_VULNS = {
    "jQuery": [
        (lambda v: v < (3, 5, 0), "CVE-2020-11022/11023 — XSS via htmlPrefilter() in jQuery < 3.5.0"),
        (lambda v: v < (3, 4, 0), "CVE-2019-11358 — Prototype pollution in jQuery < 3.4.0"),
    ],
    "Bootstrap": [
        (lambda v: v < (4, 3, 1), "CVE-2019-8331 — XSS in tooltip/popover data-template before 4.3.1"),
    ],
    "AngularJS": [
        (lambda v: v < (1, 8, 0), "CVE-2020-7676 — DOM-based XSS in AngularJS < 1.8.0"),
    ],
    "Lodash": [
        (lambda v: v < (4, 17, 21), "CVE-2021-23337 — Command injection in Lodash < 4.17.21"),
        (lambda v: v < (4, 17, 12), "CVE-2019-10744 — Prototype pollution in Lodash < 4.17.12"),
    ],
    "Handlebars": [
        (lambda v: v < (4, 3, 0), "CVE-2019-19919 — Prototype pollution in Handlebars < 4.3.0"),
    ],
    "Moment.js": [
        (lambda v: v < (2, 29, 4), "CVE-2022-31129 — ReDoS in Moment.js < 2.29.4"),
    ],
}

def _parse_version(vstr):
    try:
        parts = tuple(int(p) for p in vstr.split(".")[:3])
        return parts + (0,) * (3 - len(parts))
    except Exception:
        return (0, 0, 0)

def scan_js_libraries(response):
    """Scans the page HTML for <script> references to common front-end libraries
    and flags any whose detected version matches a known-vulnerable range.
    Primary vuln source is a live OSV.dev query (lookup_osv_vuln); falls back
    to the static KNOWN_JS_VULNS table only if that query fails."""
    if not response:
        return []
    body = response.text
    detected = {}
    for pattern, lib_name in JS_LIB_PATTERNS:
        match = re.search(pattern, body, re.IGNORECASE)
        if match and lib_name not in detected:
            detected[lib_name] = match.group(1)

    # Fallback pass: libraries present with no discoverable version string
    # (e.g. a plain "jquery.min.js" filename, or the name only appearing in
    # a bundler-hashed asset). We still want these to show up in the report
    # instead of silently vanishing — just without a vuln verdict, since we
    # can't compare an unknown version against a CVE database without one.
    for pattern, lib_name in JS_LIB_NAME_ONLY:
        if lib_name not in detected and re.search(pattern, body, re.IGNORECASE):
            detected[lib_name] = None

    _osv_items = [(n, v) for n, v in detected.items() if v is not None]
    _osv_map = dict(zip([n for n, _ in _osv_items], _pmap(lambda nv: lookup_osv_vuln(nv[0], nv[1]), _osv_items, 6)))

    results = []
    for lib_name, version in detected.items():
        if version is None:
            results.append({
                "Library": lib_name,
                "Detected Version": "Unknown (no version string found)",
                "Status": "UNKNOWN",
                "Known Issues": "Library detected but version could not be determined — cannot check against known CVEs."
            })
            continue

        osv_findings = _osv_map.get(lib_name)
        if osv_findings is not None:
            # OSV.dev answered (even if the answer was "zero vulns") — trust it,
            # this is always current since it's a live query, not a static list.
            results.append({
                "Library": lib_name,
                "Detected Version": version,
                "Status": "VULNERABLE" if osv_findings else "PASS",
                "Known Issues": " | ".join(osv_findings) if osv_findings else "No known vulnerabilities found for this version (source: OSV.dev, live)."
            })
        else:
            # OSV.dev unreachable — fall back to the hand-curated offline table.
            parsed_v = _parse_version(version)
            vulns = [desc for check_fn, desc in KNOWN_JS_VULNS.get(lib_name, []) if check_fn(parsed_v)]
            results.append({
                "Library": lib_name,
                "Detected Version": version,
                "Status": "VULNERABLE" if vulns else "PASS",
                "Known Issues": (" | ".join(vulns) if vulns else "No known vulnerabilities for this version in our offline reference set.") + " (OSV.dev unreachable — used offline fallback list, may be outdated.)"
            })
    return results

def check_single_port(ip, port):
    info = PORT_RISK_MAP.get(port, {"service": "Unknown", "risk": "MEDIUM", "threat": "Unknown Port Threat"})
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(1.0)
        res = s.connect_ex((ip, port))
        s.close()
        status = "OPEN" if res == 0 else "CLOSED"
        return port, info["service"], status, info["risk"] if status == "OPEN" else "SAFE", info["threat"] if status == "OPEN" else "No Threat (Closed)"
    except:
        return port, info["service"], "CLOSED", "SAFE", "No Threat (Closed)"

def scan_ports(host, max_workers=10):
    port_results = []
    try: ip = socket.gethostbyname(host)
    except socket.gaierror: return [{"Port": "N/A", "Service": "N/A", "Status": "Host Resolution Failed", "Risk Level": "N/A", "Potential Threat": "N/A"}]

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = [executor.submit(check_single_port, ip, p) for p in PORT_RISK_MAP.keys()]
        for future in futures:
            port, service, status, risk, threat = future.result()
            port_results.append({"Port": port, "Service": service, "Status": status, "Risk Level": risk, "Potential Threat": threat})

    return sorted(port_results, key=lambda x: x["Port"])

def audit_security_headers(headers):
    headers_lower = {k.lower(): v for k, v in headers.items()}
    audit_results = []
    req_headers = {
        "strict-transport-security": "HSTS Header",
        "content-security-policy": "CSP Header",
        "x-frame-options": "X-Frame-Options",
        "x-content-type-options": "X-Content-Type-Options",
        "referrer-policy": "Referrer-Policy",
        "permissions-policy": "Permissions-Policy",
        "access-control-allow-origin": "CORS Policy"
    }
    for h_key, h_name in req_headers.items():
        if h_key in headers_lower:
            val = headers_lower[h_key]
            status = "Optimization Needed" if val == "*" or "unsafe-inline" in val else "PASS"
            audit_results.append({"Header": h_name, "Status": status, "Value": val})
        else:
            audit_results.append({"Header": h_name, "Status": "Action Required", "Value": "Not Configured"})
    return audit_results

def analyze_tls_ssl(host, port=443):
    ssl_data = {"status": "Unknown", "expiry": "Unknown", "issuer": "Unknown", "cipher": "Unknown", "version": "Unknown"}
    try:
        context = ssl.create_default_context()
        with socket.create_connection((host, port), timeout=4) as sock:
            with context.wrap_socket(sock, server_hostname=host) as ssock:
                cert = ssock.getpeercert()
                ssl_data["version"] = ssock.version()
                ssl_data["cipher"] = ssock.cipher()[0]
                ssl_data["status"] = "Valid TLS Certificate"
                if cert.get('notAfter'): ssl_data["expiry"] = cert.get('notAfter')
                issuer = dict(x[0] for x in cert.get('issuer', []))
                ssl_data["issuer"] = issuer.get('organizationName', issuer.get('commonName', 'Unknown'))
    except Exception as e:
        ssl_data["status"] = "TLS Audit Required"
        ssl_data["details"] = str(e)
    return ssl_data

def audit_cookies(response):
    cookie_results = []
    if not response.cookies:
        return [{"Name": "None Found", "Secure": "N/A", "HttpOnly": "N/A", "Status": "PASS", "Issues": "No cookies issued by web server"}]

    for cookie in response.cookies:
        issues = []
        if not cookie.secure: issues.append("Missing 'Secure'")
        if not cookie.has_nonstandard_attr('HttpOnly') and not cookie._rest.get('httponly'): issues.append("Missing 'HttpOnly'")
        cookie_results.append({
            "Name": cookie.name, "Secure": str(cookie.secure),
            "HttpOnly": str(bool(cookie._rest.get('httponly'))),
            "Status": "PASS" if not issues else "Optimization Needed",
            "Issues": ", ".join(issues) if issues else "Fully Secured"
        })
    return cookie_results

def _get_spa_fallback_baseline(base_url):
    """Many modern sites (React/Vue/Angular SPAs, e.g. WhatsApp Web-style apps)
    serve the same index.html 'app shell' for ANY unknown path with a 200 status,
    because routing happens client-side. Without this baseline, every path in
    SENSITIVE_PATHS looks 'EXPOSED (200 OK)' even though the server is just doing
    its normal catch-all routing and nothing was actually leaked. We probe a
    random, definitely-nonexistent path first and use its response as a
    fingerprint to recognize (and discount) that fallback behavior."""
    import uuid
    probe_path = f"/__argus_probe_{uuid.uuid4().hex[:12]}"
    try:
        r = requests.get(base_url.rstrip("/") + probe_path, timeout=3,
                          allow_redirects=False, headers={"User-Agent": f"ARGUS/{ARGUS_VERSION}"})
        if r.status_code == 200:
            return {"len": len(r.content), "hash": hash(r.content)}
    except Exception:
        pass
    return None

def check_single_path(base_url, path, spa_baseline=None):
    target = base_url.rstrip("/") + path
    try:
        r = requests.get(target, timeout=3, allow_redirects=False, headers={"User-Agent": f"ARGUS/{ARGUS_VERSION}"})
        if r.status_code == 200:
            # If this 200 response is byte-identical (or same length) to the
            # random-nonexistent-path baseline, it's the SPA's catch-all shell,
            # not a real file exposure — don't count it as EXPOSED.
            if spa_baseline and len(r.content) == spa_baseline["len"] and hash(r.content) == spa_baseline["hash"]:
                return path, "Clean (SPA fallback, 200)", len(r.content)
            return path, "EXPOSED (200 OK)", len(r.content)
        elif r.status_code in [301, 302]: return path, f"Redirect ({r.status_code})", 0
        elif r.status_code == 403: return path, "Protected (403)", 0
        else: return path, f"Clean ({r.status_code})", 0
    except: return path, "Error", 0

def run_misconfig_checks(base_url, max_workers=10):
    results = {}
    spa_baseline = _get_spa_fallback_baseline(base_url)
    all_paths = SENSITIVE_PATHS + INFORMATIONAL_PATHS
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {executor.submit(check_single_path, base_url, path, spa_baseline): path for path in all_paths}
        for future in futures:
            path, status, size = future.result()
            if "EXPOSED" in status or "Protected" in status:
                results[path] = {
                    "status": status, "size": size,
                    "informational": path in INFORMATIONAL_PATHS
                }
    return results

def run_owasp_top10_audit(scan_data):
    owasp_results = []
    headers = scan_data.get("headers_dict", {})
    
    misconfig = scan_data.get("misconfig", {})
    # Only genuinely sensitive paths count toward A01 — robots.txt/sitemap.xml
    # are informational (meant to be public) and are excluded here even if
    # they show up in the misconfig dict.
    exposed_sensitive = [
        k for k, v in misconfig.items()
        if "EXPOSED" in v.get("status", "") and not v.get("informational", False)
    ]
    owasp_results.append({
        "OWASP Category": "A01:2021 - Broken Access Control",
        "Status": "VULNERABLE" if exposed_sensitive else "PASS",
        "Details": f"Exposed Sensitive Paths: {', '.join(exposed_sensitive) if exposed_sensitive else 'None'}"
    })

    ssl_info = scan_data.get("ssl", {})
    has_hsts = any(h["Header"] == "HSTS Header" and h["Status"] == "PASS" for h in scan_data.get("headers", []))
    owasp_results.append({
        "OWASP Category": "A02:2021 - Cryptographic Failures",
        "Status": "PASS" if ssl_info.get("status") == "Valid TLS Certificate" and has_hsts else "WARNING",
        "Details": f"TLS Valid: {ssl_info.get('status') == 'Valid TLS Certificate'} | HSTS Enabled: {has_hsts}"
    })

    has_csp = any(h["Header"] == "CSP Header" and h["Status"] == "PASS" for h in scan_data.get("headers", []))
    owasp_results.append({
        "OWASP Category": "A03:2021 - Injection / XSS Mitigation",
        "Status": "PASS" if has_csp else "WARNING",
        "Details": "CSP Header configured properly" if has_csp else "CSP Header missing or weak"
    })

    server_hdr = headers.get("server", "Not Disclosed")
    powered_by = headers.get("x-powered-by", "Not Disclosed")
    owasp_results.append({
        "OWASP Category": "A05:2021 - Security Misconfiguration",
        "Status": "WARNING" if server_hdr != "Not Disclosed" or powered_by != "Not Disclosed" else "PASS",
        "Details": f"Server Info Leakage: Server ({server_hdr}), X-Powered-By ({powered_by})"
    })

    ports = scan_data.get("ports", [])
    open_critical_ports = [f"{p['Port']}({p['Service']})" for p in ports if p["Status"] == "OPEN" and p["Risk Level"] in ["CRITICAL", "HIGH"]]
    owasp_results.append({
        "OWASP Category": "A06:2021 - Vulnerable Components & Exposed Ports",
        "Status": "VULNERABLE" if open_critical_ports else "PASS",
        "Details": f"Exposed High-Risk Open Ports: {', '.join(open_critical_ports) if open_critical_ports else 'None'}"
    })

    cookies = scan_data.get("cookies", [])
    insecure_cookies = [c["Name"] for c in cookies if c["Status"] != "PASS" and c["Name"] != "None Found"]
    owasp_results.append({
        "OWASP Category": "A07:2021 - Identification & Auth Failures",
        "Status": "WARNING" if insecure_cookies else "PASS",
        "Details": f"Insecure Session Cookie Flags: {', '.join(insecure_cookies) if insecure_cookies else 'None'}"
    })

    return owasp_results

