def lookup_cves_for_tech(tech_keywords, nvd_api_key="", max_keywords=2, results_per_keyword=3):
    """
    Cross-references the detected technology stack against the NIST National
    Vulnerability Database (NVD) via keyword search. No extra library needed —
    just the public NVD REST API over `requests`. Capped to a couple of keywords
    per scan to stay polite to NVD's public rate limit (5 req/30s without a key,
    50 req/30s with one).

    NOTE: this previously took the human-readable tech_stack display STRING
    (e.g. "Powered-By: Express, WordPress CMS, React.js Frontend") and tried
    to re-derive search keywords from it by splitting on commas/colons. That
    left junk tokens like "Powered-By" and multi-word phrases like "React.js
    Frontend" that don't match any real NVD product name, so the CVE tab
    always came back empty. It now takes the clean keyword list that
    detect_waf_and_tech() builds directly (e.g. ["Express", "WordPress",
    "React"]) instead of re-parsing the display string.
    """
    if not tech_keywords:
        return []

    keywords = list(dict.fromkeys(k.strip() for k in tech_keywords if k and len(k.strip()) >= 3))[:max_keywords]
    if not keywords:
        return []

    headers = {"apiKey": nvd_api_key} if nvd_api_key else {}

    def _nvd(kw):
        out = []
        try:
            resp = requests.get(
                "https://services.nvd.nist.gov/rest/json/cves/2.0",
                params={"keywordSearch": kw, "resultsPerPage": results_per_keyword},
                headers=headers, timeout=6
            )
            if resp.status_code != 200:
                return out
            for vuln in resp.json().get("vulnerabilities", []):
                cve = vuln.get("cve", {})
                descs = cve.get("descriptions", [])
                desc_text = next((d["value"] for d in descs if d.get("lang") == "en"), "No description available.")
                severity = "UNKNOWN"
                for metric_key in ["cvssMetricV31", "cvssMetricV30", "cvssMetricV2"]:
                    m = cve.get("metrics", {}).get(metric_key)
                    if m:
                        severity = m[0].get("cvssData", {}).get("baseSeverity", "UNKNOWN")
                        break
                out.append({
                    "CVE ID": cve.get("id", "N/A"),
                    "Severity": severity,
                    "Keyword": kw,
                    "Published": cve.get("published", "N/A")[:10],
                    "Description": (desc_text[:180] + "…") if len(desc_text) > 180 else desc_text,
                })
        except Exception:
            pass
        return out

    findings = [f for chunk in _pmap(_nvd, keywords, 2) for f in chunk]
    return findings

def map_owasp_to_compliance(owasp_results):
    """Maps each OWASP Top 10 finding to PCI-DSS / ISO 27001 / GDPR control references."""
    rows = []
    for item in owasp_results:
        cat = item.get("OWASP Category", "")
        mapping = COMPLIANCE_MAP.get(cat, DEFAULT_COMPLIANCE_ROW)
        rows.append({
            "OWASP Category": cat,
            "Status": item.get("Status", ""),
            "PCI-DSS v4.0": mapping["pci"],
            "ISO/IEC 27001:2022": mapping["iso"],
            "GDPR": mapping["gdpr"],
        })
    return rows

def capture_website_screenshot(url):
    """
    Lightweight visual-recon capture via thum.io's free rendering endpoint (no signup
    needed for light use). Returns a base64-encoded image string so it stays JSON-safe
    for the raw telemetry export, or None on failure. For production-grade reliability
    at scale, swap this for a paid screenshot API or a self-hosted headless browser
    (Selenium/Playwright) worker.
    """
    try:
        shot_url = f"https://image.thum.io/get/width/900/crop/650/noanimate/{url}"
        resp = requests.get(shot_url, timeout=15)
        if resp.status_code == 200 and resp.content and len(resp.content) > 500:
            return base64.b64encode(resp.content).decode("utf-8")
    except Exception:
        pass
    return None


