# ---------------------------------------------------------
# Master HUD Execution Engine
# ---------------------------------------------------------
def scan_target_with_hud(url, progress_bar, terminal_placeholder):
    start_time = time.time()
    formatted_url = format_url(url)
    parsed = urlparse(formatted_url)
    host = parsed.hostname if parsed.hostname else url

    results = {"url": formatted_url, "host": host}
    logs = [f"[INIT] Initializing ARGUS v{ARGUS_VERSION} for target: {host}..."]

    def update_hud(text, progress):
        logs.append(f"[{datetime.now().strftime('%H:%M:%S')}] {text}")
        term_html = "<div class='cyber-terminal'>" + "<br>".join(logs[-6:]) + "</div>"
        terminal_placeholder.markdown(term_html, unsafe_allow_html=True)
        progress_bar.progress(progress)

    update_hud("MEM_DUMP: Allocating thread execution buffers...", 10)

    try:
        response = throttled_request(requests.get, formatted_url, delay_range, timeout=5,
                                      headers={"User-Agent": f"ARGUS/{ARGUS_VERSION}"})
        results["waf"], results["tech_stack"], results["tech_stack_keywords"] = detect_waf_and_tech(response)
        results["headers_dict"] = dict(response.headers)
    except:
        response = None
        results["waf"], results["tech_stack"], results["tech_stack_keywords"] = "Error Checking WAF", "Unknown", []
        results["headers_dict"] = {}

    # ---- Instant checks (reuse the first response, no extra network) ----
    update_hud("MODULE 3 / 5 / 6: Auditing Security Headers, Cookies & HTTP status...", 20)
    if run_headers and response: results["headers"] = audit_security_headers(response.headers)
    if run_cookies and response: results["cookies"] = audit_cookies(response)
    elif run_cookies: results["cookies"] = [{"Name": "N/A", "Secure": "N/A", "HttpOnly": "N/A", "Status": "PASS", "Issues": "Target unreachable"}]
    if run_http: results["http"] = {"status": response.status_code if response else "Failed"}

    # ---- Phase A: all independent network modules run CONCURRENTLY ----
    stealth = delay_range[1] >= 1.0
    port_workers = timing_workers if stealth else max(timing_workers, 30)
    http_workers = timing_workers if stealth else max(timing_workers, 20)
    phase_a = []
    if run_recon:         phase_a.append(("recon", "MODULE 1: Recon & DNS", lambda: perform_recon(host, formatted_url)))
    if run_ports:         phase_a.append(("ports", "MODULE 2: Port scan", lambda: scan_ports(host, max_workers=port_workers)))
    if run_ssl:           phase_a.append(("ssl", "MODULE 4: TLS / SSL", lambda: analyze_tls_ssl(host)))
    if run_misconfig:     phase_a.append(("misconfig", "MODULE 7: Sensitive paths", lambda: run_misconfig_checks(formatted_url, max_workers=http_workers)))
    if run_email_sec:     phase_a.append(("email_sec", "MODULE 9: SPF / DKIM / DMARC", lambda: check_email_security(host)))
    if run_js_libs:       phase_a.append(("js_libs", "MODULE 10: JS library CVEs", lambda: scan_js_libraries(response)))
    if run_cve_lookup:    phase_a.append(("cve_findings", "PRO: NVD CVE lookup", lambda: lookup_cves_for_tech(results.get("tech_stack_keywords", []), nvd_api_key)))
    if run_screenshot:    phase_a.append(("screenshot_b64", "PRO: Screenshot", lambda: capture_website_screenshot(results["url"])))
    if run_attack_surface: phase_a.append(("attack_surface", "PRO: Attack surface", lambda: run_attack_surface_scan(host, host, delay_range)))
    if run_api_security:  phase_a.append(("api_security", "PRO: API surface", lambda: run_api_security_scan(formatted_url, response, delay_range)))

    if phase_a:
        module_workers = max(2, min(timing_workers, 10))
        update_hud(f"PARALLEL ENGINE: launching {len(phase_a)} modules on {module_workers} threads...", 25)
        done = 0
        with ThreadPoolExecutor(max_workers=module_workers) as pool:
            fut_map = {pool.submit(fn): (key, label) for key, label, fn in phase_a}
            for fut in as_completed(fut_map):
                key, label = fut_map[fut]
                done += 1
                pct = 25 + int(done / len(phase_a) * 60)
                try:
                    results[key] = fut.result()
                    update_hud(f"✔ {label} complete", pct)
                except Exception as e:
                    update_hud(f"✖ {label} failed: {str(e)[:70]}", pct)

    # ---- Phase B: modules that depend on Phase A results ----
    if run_owasp:
        update_hud("MODULE 8: OWASP Top 10 Automated Vulnerability Mapping...", 88)
        results["owasp"] = run_owasp_top10_audit(results)

    if run_compliance_mapping and "owasp" in results:
        update_hud("PRO MODULE: Mapping Findings to PCI-DSS / ISO 27001 / GDPR...", 91)
        results["compliance"] = map_owasp_to_compliance(results["owasp"])

    if run_supply_chain:
        update_hud("PRO MODULE: Building SBOM & Scanning for Leaked Secrets...", 94)
        results["supply_chain"] = run_supply_chain_scan(formatted_url, response, results.get("js_libs", []), delay_range)

    if run_threat_intel:
        update_hud("PRO MODULE: Checking Breach Database Exposure...", 96)
        results["threat_intel"] = check_threat_intel(host)

    if run_reporting_interop and "owasp" in results:
        update_hud("PRO MODULE: Mapping Findings to MITRE ATT&CK & Building SARIF...", 97)
        results["attack_mapping"] = map_findings_to_attack(results["owasp"])

    if gemini_api_key:
        update_hud(f"GEMINI AI ({selected_gemini_model}): Generating Step-by-Step Remediation Recommendations...", 98)
        results["ai_analysis"] = run_gemini_remediation_guidance(gemini_api_key, selected_gemini_model, results)

    end_time = time.time()
    scan_duration = end_time - start_time
    update_hud(f"[COMPLETE] Assessment finished in {scan_duration:.2f} seconds.", 100)

    return results, scan_duration

# ---------------------------------------------------------
# Reusable Report Renderers (Single-Target & Bulk Monitoring Wall)
# ---------------------------------------------------------
def render_single_report(res, health_score, duration, key_suffix=""):
    """Renders the full metrics + chart + downloads + tabs block for one scanned target.
    Used both for the single-scan flow and inside each Bulk-mode expander."""
    _, passed, warnings, critical = calculate_security_health(res)
    host = res.get("host", "N/A")
    uid = f"{key_suffix}_{host}"

    c1, c2, c3, c4 = st.columns(4)
    c1.metric("TARGET HOST", host)
    c2.metric("SCAN DURATION", f"{duration:.2f}s")
    c3.metric("HEALTH SCORE", f"{health_score}%")
    c4.metric("WAF STATUS", res.get("waf", "N/A"))

    st.markdown("<br>", unsafe_allow_html=True)

    col_metrics, col_chart = st.columns([3, 2])
    with col_metrics:
        st.markdown("#### 📊 Scan Summary")
