def render_quad_card(item, idx):
    """One tile on the Bulk-mode monitoring wall — a compact live-status card."""
    res, health, critical = item["res"], item["health"], item["critical"]
    host = res.get("host", "Unknown")

    if critical > 3:
        badge_class, status_text, card_class = "badge-crit", "🔴 CRITICAL ISSUES", " quad-error"
    elif critical > 0:
        badge_class, status_text, card_class = "badge-warn", "🟡 NEEDS ATTENTION", ""
    else:
        badge_class, status_text, card_class = "badge-pass", "🟢 SECURE", ""

    thumb_html = ""
    if res.get("screenshot_b64"):
        thumb_html = f'<img class="quad-thumb" src="data:image/png;base64,{res["screenshot_b64"]}" />'

    st.markdown(f"""
    <div class="quad-card{card_class}">
        {thumb_html}
        <div class="quad-host">{host}</div>
        <div class="quad-status"><span class="{badge_class}">{status_text}</span></div>
        <div class="quad-meta">Health Score: <b>{health}%</b></div>
        <div class="quad-meta">WAF: {res.get('waf', 'N/A')}</div>
        <div class="quad-meta">Critical Findings: {critical}</div>
    </div>
    """, unsafe_allow_html=True)

def render_monitoring_wall(bulk_results):
    """Splits scanned targets into 4-per-screen quadrant pages (a mini SOC video wall),
    then lists a full drill-down report per target underneath."""
    st.markdown("### 🖥️ Multi-Target Monitoring Wall")
    st.caption(f"{len(bulk_results)} target(s) scanned — grouped 4-per-screen, tab through to page across targets.")

    chunk_size = 4
    chunks = [bulk_results[i:i + chunk_size] for i in range(0, len(bulk_results), chunk_size)]
    screen_tabs = st.tabs([f"🖥️ Screen {i + 1}" for i in range(len(chunks))])

    g_idx = 0
    for screen_tab, chunk in zip(screen_tabs, chunks):
        with screen_tab:
            slots = st.columns(2) + st.columns(2)
            for slot, item in zip(slots, chunk):
                with slot:
                    render_quad_card(item, g_idx)
                    g_idx += 1

    st.markdown("<br>", unsafe_allow_html=True)
    st.markdown("### 📋 Full Drill-Down Reports")
    for i, item in enumerate(bulk_results):
        res = item["res"]
        with st.expander(f"{res.get('host', '?')} — Health {item['health']}% | Critical: {item['critical']}"):
            render_single_report(res, item["health"], item["duration"], key_suffix=f"bulk{i}")

