# ---------------------------------------------------------
# Build the module chip list as plain Python first. Doing the conditional
# assembly here (instead of inline inside the multi-line HTML string) avoids
# the whitespace-only lines that were left behind when a chip was hidden —
# those blank lines were breaking the raw HTML block early and causing the
# literal "</div>" text to leak out and render as its own badge.
chip_items = ["🔎 Recon", "🔌 Ports", "🛡️ Headers", "🔐 TLS/SSL", "🔥 OWASP", "📧 Email Sec", "📦 JS Libs", "🤖 AI Remediation"]
if run_cve_lookup: chip_items.append("🦠 CVE Intel")
if run_compliance_mapping: chip_items.append("📋 Compliance")
if run_screenshot: chip_items.append("📸 Screenshot")
if run_attack_surface: chip_items.append("🌐 Attack Surface")
if run_api_security: chip_items.append("🔌 API Security")
if run_supply_chain: chip_items.append("📦 Supply Chain")
if run_threat_intel: chip_items.append("🕵️ Threat Intel")
if run_reporting_interop: chip_items.append("🗺️ ATT&CK/SARIF")
chips_html = "".join(f"<span class='chip'>{c}</span>" for c in chip_items)
pro_badge_html = "<div><span class='pro-badge'>🚀 PRO MODE ACTIVE</span></div>" if pro_mode else ""

st.markdown(
    f'<div class="creator-bar">Created by <a href="{ARGUS_AUTHOR_URL}" target="_blank">{ARGUS_AUTHOR_URL}</a></div>'
    f'<div class="hero"><img class="argus-logo" src="data:image/png;base64,{ARGUS_LOGO_B64}" alt="ARGUS"/>'
    f'<div><span class="ver-tag">v{ARGUS_VERSION}</span></div>'
    f'<p class="hero-sub">Next-Gen Multi-Module Threat Reconnaissance &amp; AI Remediation Engine</p>'
    f'<div class="chip-row">{chips_html}</div>'
    f'{pro_badge_html}</div>',
    unsafe_allow_html=True
)

st.markdown(
    '<div class="argus-note">💡 For a high-level scan, use the Gemini &amp; NVD API keys and enable Pro Mode. Thank you!</div>',
    unsafe_allow_html=True
)

if "bulk_results" not in st.session_state:
    st.session_state.bulk_results = []

if not bulk_mode:
    # ---------------- Single-Target Mode ----------------
    col_input, col_btn = st.columns([4, 1])
    with col_input:
        target_url = st.text_input("Target Domain / URL:", placeholder="example.com", label_visibility="collapsed")
    with col_btn:
        start_btn = st.button("Start Assessment", width="stretch")

    if start_btn:
        if target_url:
            progress_bar = st.progress(0)
            terminal_placeholder = st.empty()

            res, duration = scan_target_with_hud(target_url, progress_bar, terminal_placeholder)
            health_score, passed, warnings, critical = calculate_security_health(res)

            st.success(f"Assessment Complete for {res['host']}!")
            render_single_report(res, health_score, duration, key_suffix="single")
        else:
            st.error("Please enter a target URL.")

else:
    # ---------------- Bulk / Multi-Target Mode ----------------
    st.markdown("#### 🗂️ Bulk Multi-Target Scan")
    st.caption("Enter one domain per line. Each target is scanned sequentially, then plotted on the 4-per-screen monitoring wall below.")

    targets_raw = st.text_area(
        "Target list:", height=120,
        placeholder="example.com\nanother-site.net\nthird-target.org",
        label_visibility="collapsed"
    )
    start_bulk = st.button("🚀 Start Bulk Assessment", width="stretch")

    if start_bulk:
        targets = [t.strip() for t in targets_raw.splitlines() if t.strip()]
        if not targets:
            st.error("Please enter at least one target domain.")
        elif len(targets) > 12:
            st.error("Bulk mode is capped at 12 targets per run to keep scans responsive — please split into smaller batches.")
        else:
            new_bulk_results = []
            overall_status = st.empty()
            for i, t in enumerate(targets):
                overall_status.info(f"🔄 Scanning target {i + 1} of {len(targets)}: **{t}**")
                sub_progress = st.progress(0)
                sub_terminal = st.empty()
                res, dur = scan_target_with_hud(t, sub_progress, sub_terminal)
                health, passed, warnings, critical = calculate_security_health(res)
                new_bulk_results.append({
                    "res": res, "health": health, "passed": passed,
                    "warnings": warnings, "critical": critical, "duration": dur
                })
                sub_progress.empty()
                sub_terminal.empty()
            overall_status.success(f"✅ Bulk assessment complete — {len(targets)} target(s) scanned.")
            st.session_state.bulk_results = new_bulk_results

    if st.session_state.bulk_results:
        st.markdown("<br>", unsafe_allow_html=True)
        render_monitoring_wall(st.session_state.bulk_results)